export const TRICK_KEY = "paddlefish";
export const TRICKS = ["rostrumscan", "filterram", "rivercruise", "eggcast", "ampullae", "cartilaginous", "spathula"] as const;
export const HAPPY = ["densspoon", "inkspoon", "densrostrum"] as const;
export type PaddlefishTrickKind = (typeof TRICKS)[number];
export type PaddlefishHappyKind = (typeof HAPPY)[number];
export type TrickAnim = "idle" | "walk" | "sit" | "sleep" | "talk" | "play";
export type TrickPhase = "go" | "hold" | "release" | "done";
export type HappyPhase = "go" | "done";

export type TrickFlags = {
  asleep?: boolean;
  hidden?: boolean;
  leaving?: boolean;
  cmd?: string;
  windowPlay?: boolean;
  card?: boolean;
};

export type PaddlefishTrick = {
  kind: PaddlefishTrickKind;
  phase: TrickPhase;
  t: number;
  x: number;
  lift: number;
  rot: number;
  anim: TrickAnim;
  facing: 1 | -1;
  fromX: number;
  abort?: boolean;
};

export type PaddlefishHappy = {
  kind: PaddlefishHappyKind;
  happy: true;
  phase: HappyPhase;
  t: number;
  x: number;
  lift: number;
  rot: number;
  anim: TrickAnim;
  facing: 1 | -1;
  fromX: number;
  abort?: boolean;
};

export const HAPPY_DUR = { densspoon: 1.70, inkspoon: 1.84, densrostrum: 1.76 } as const;
export const SPATHULA_HOLD = 11.2;
export const RELEASE_S = 1.18;
export const DUR = {
  spathula: SPATHULA_HOLD + RELEASE_S,
  rostrumscan: 2.48,
  filterram: 2.56,
  rivercruise: 2.42,
  eggcast: 2.38,
  ampullae: 2.40,
  cartilaginous: 2.44,
} as const;

export function canStart(state: TrickFlags | undefined) {
  if (!state) return false;
  if (state.asleep || state.hidden || state.leaving || state.windowPlay || state.card) return false;
  const cmd = String(state.cmd || "");
  if (cmd === "sleep" || cmd === "leave" || cmd === "hide" || cmd === "rest") return false;
  if (cmd === "seek" || cmd === "eat" || cmd === "play" || cmd === "talk" || cmd === "enter") return false;
  return true;
}

export function shouldAbort(state: TrickFlags | undefined) {
  if (!state) return true;
  if (state.asleep || state.hidden || state.leaving || state.windowPlay || state.card) return true;
  const cmd = String(state.cmd || "");
  return (
    cmd === "sleep" ||
    cmd === "leave" ||
    cmd === "hide" ||
    cmd === "rest" ||
    cmd === "seek" ||
    cmd === "eat" ||
    cmd === "play" ||
    cmd === "talk" ||
    cmd === "enter"
  );
}

export function nextTrickWait(justFinished: boolean, rand?: number, kind?: PaddlefishTrickKind | string) {
  const roll = rand == null ? Math.random() : rand;
  if (kind === "spathula") return 40 + roll * 26;
  if (kind === "ampullae" || kind === "eggcast" || kind === "rostrumscan") return 12.8 + roll * 9.4;
  if (kind === "filterram" || kind === "rivercruise" || kind === "cartilaginous") return 11.6 + roll * 8.5;
  return justFinished ? 8.5 + roll * 8.4 : 4.4 + roll * 7.4;
}


